<template>
  <div class="divBox">
    <el-card shadow="never">
      <div slot="header" class="header"><span>收益奖励规则</span><el-tag type="warning">能力完整 · 默认关闭</el-tag></div>
      <el-alert title="保存只生成草稿。规则必须先试算，再填写生效时间并发布。未发布、已停用或不在生效窗口的规则不会产生可提现佣金。" type="warning" :closable="false" style="margin-bottom:16px" />
      <el-form inline size="small">
        <el-form-item label="业务来源"><el-select v-model="query.sourceType" clearable><el-option v-for="x in sourceTypes" :key="x.value" :label="x.label" :value="x.value" /></el-select></el-form-item>
        <el-form-item label="受益身份"><el-select v-model="query.receiverRoleCode" clearable><el-option v-for="x in roleOptions" :key="x.roleCode" :label="x.roleName" :value="x.roleCode" /></el-select></el-form-item>
        <el-form-item label="业务开关"><el-select v-model="query.status" clearable><el-option label="启用" :value="true"/><el-option label="关闭" :value="false"/></el-select></el-form-item>
        <el-button type="primary" @click="load">查询</el-button><el-button type="success" @click="openRule()">新增草稿</el-button>
      </el-form>
      <el-table v-loading="loading" :data="list" size="mini">
        <el-table-column prop="ruleCode" label="规则编码" min-width="150"/><el-table-column prop="ruleName" label="规则名称" min-width="170"/>
        <el-table-column label="来源" width="120"><template slot-scope="s">{{s.row.sourceTypeText||s.row.sourceType}}</template></el-table-column>
        <el-table-column label="奖励类型" min-width="150"><template slot-scope="s">{{rewardLabel(s.row.rewardType)}}</template></el-table-column>
        <el-table-column label="受益身份" width="120"><template slot-scope="s">{{s.row.receiverRoleName||s.row.receiverRoleCode||'--'}}</template></el-table-column>
        <el-table-column label="计算" width="130"><template slot-scope="s">{{calcText(s.row)}}</template></el-table-column>
        <el-table-column prop="versionNo" label="版本" width="70"/>
        <el-table-column label="发布状态" width="120"><template slot-scope="s"><el-tag :type="publishTag(s.row.publishStatus)">{{s.row.publishStatusText||s.row.publishStatus||'草稿'}}</el-tag></template></el-table-column>
        <el-table-column label="生效窗口" min-width="220"><template slot-scope="s">{{s.row.effectiveStartTime||'未发布'}}<br>{{s.row.effectiveEndTime||'长期'}}</template></el-table-column>
        <el-table-column label="操作" width="260"><template slot-scope="s"><el-button type="text" :disabled="s.row.publishStatus==='PUBLISHED'" @click="openRule(s.row)">编辑</el-button><el-button type="text" @click="openTrial(s.row)">试算</el-button><el-button v-if="s.row.publishStatus!=='PUBLISHED'" type="text" @click="openPublish(s.row)">发布</el-button><el-button v-else type="text" class="danger" @click="disableRule(s.row)">停用</el-button></template></el-table-column>
      </el-table>
    </el-card>

    <el-dialog :title="form.id?'编辑规则草稿':'新增规则草稿'" :visible.sync="formVisible" width="820px">
      <el-form label-width="130px" size="small">
        <el-row :gutter="18"><el-col :span="12"><el-form-item label="规则名称" required><el-input v-model.trim="form.ruleName"/></el-form-item></el-col><el-col :span="12"><el-form-item label="规则编码" required><el-input v-model.trim="form.ruleCode" placeholder="如 MAKER_DIRECT_RETAIL"/></el-form-item></el-col></el-row>
        <el-row :gutter="18"><el-col :span="12"><el-form-item label="业务来源" required><el-select v-model="form.sourceType" style="width:100%"><el-option v-for="x in sourceTypes" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="奖励类型" required><el-select v-model="form.rewardType" style="width:100%"><el-option v-for="x in rewardTypes" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item></el-col></el-row>
        <el-row :gutter="18"><el-col :span="12"><el-form-item label="受益身份" required><el-select v-model="form.receiverRoleCode" style="width:100%"><el-option v-for="x in roleOptions" :key="x.roleCode" :label="x.roleName" :value="x.roleCode"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="受益人来源" required><el-select v-model="form.beneficiaryType" style="width:100%"><el-option v-for="x in beneficiaryTypes" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item></el-col></el-row>
        <el-row :gutter="18"><el-col :span="12"><el-form-item label="计算基数" required><el-select v-model="form.baseType" style="width:100%"><el-option v-for="x in baseTypes" :key="x.value" :label="x.label" :value="x.value"/></el-select></el-form-item></el-col><el-col :span="12"><el-form-item label="计算方式" required><el-select v-model="form.calculationType" style="width:100%"><el-option label="百分比" value="PERCENT"/><el-option label="每单固定" value="FIXED_PER_ORDER"/><el-option label="每件固定" value="FIXED_PER_ITEM"/><el-option label="按数量固定" value="FIXED_PER_QUANTITY"/></el-select></el-form-item></el-col></el-row>
        <el-row :gutter="18"><el-col :span="8"><el-form-item v-if="form.calculationType==='PERCENT'" label="比例(%)"><el-input-number v-model="form.rate" :min="0" :precision="4"/></el-form-item><el-form-item v-else-if="form.calculationType==='FIXED_PER_QUANTITY'" label="单位金额"><el-input-number v-model="form.unitAmount" :min="0" :precision="2"/></el-form-item><el-form-item v-else label="固定金额"><el-input-number v-model="form.fixedAmount" :min="0" :precision="2"/></el-form-item></el-col><el-col :span="8"><el-form-item label="结算延迟(天)"><el-input-number v-model="form.settleDelayDays" :min="0"/></el-form-item></el-col><el-col :span="8"><el-form-item label="单笔封顶"><el-input-number v-model="form.perOrderCap" :min="0" :precision="2"/></el-form-item></el-col></el-row>
        <el-row :gutter="18"><el-col :span="12"><el-form-item label="叠加组"><el-input v-model.trim="form.stackGroup" placeholder="同组规则按策略处理"/></el-form-item></el-col><el-col :span="12"><el-form-item label="叠加策略"><el-select v-model="form.stackPolicy"><el-option label="只取一条" value="MAX_ONE"/><el-option label="允许叠加" value="ALLOW_STACK"/><el-option label="取最高金额" value="HIGHEST_AMOUNT"/><el-option label="取最高优先级" value="HIGHEST_PRIORITY"/></el-select><el-input-number v-model="form.priority" :min="0" style="margin-left:8px;width:100px"/></el-form-item></el-col></el-row>
        <el-form-item label="规则约束"><el-checkbox v-model="form.requiresRegisteredCustomer">必须注册客户</el-checkbox><el-checkbox v-model="form.requiresVoucher">必须有凭证</el-checkbox><el-checkbox v-model="form.requiresAudit">必须审核</el-checkbox></el-form-item>
        <el-form-item label="备注"><el-input v-model.trim="form.remark" type="textarea" :rows="3" maxlength="500"/></el-form-item>
      </el-form>
      <span slot="footer"><el-button @click="formVisible=false">取消</el-button><el-button type="primary" @click="save">保存草稿</el-button></span>
    </el-dialog>

    <el-dialog title="规则试算" :visible.sync="trialVisible" width="720px">
      <el-alert title="试算不写账户、不产生佣金记录。" type="info" :closable="false" style="margin-bottom:14px"/>
      <el-form label-width="120px" size="small"><el-form-item label="规则"><el-input :value="trialRule&&trialRule.ruleName" disabled/></el-form-item><el-form-item label="计算基数"><el-input-number v-model="trialForm.baseAmount" :min="0" :precision="2"/></el-form-item><el-form-item label="真实毛利"><el-input-number v-model="trialForm.realGrossProfit" :min="0" :precision="2"/></el-form-item><el-form-item label="数量"><el-input-number v-model="trialForm.quantity" :min="1"/></el-form-item><el-form-item label="快照用户"><el-input-number v-model="trialForm.sellerUserId" placeholder="销售人"/><el-input-number v-model="trialForm.directParentUserId" placeholder="直属上级" style="margin-left:8px"/><el-input-number v-model="trialForm.countyAgentUserId" placeholder="区县代理" style="margin-left:8px"/></el-form-item><el-form-item label="条件"><el-checkbox v-model="trialForm.registeredCustomer">注册客户</el-checkbox><el-checkbox v-model="trialForm.voucherPresent">有凭证</el-checkbox><el-checkbox v-model="trialForm.audited">已审核</el-checkbox></el-form-item></el-form>
      <el-table v-if="trialResult.length" :data="trialResult" size="mini" border><el-table-column prop="matchStatus" label="匹配结果"/><el-table-column prop="reasonCode" label="原因"/><el-table-column prop="beneficiaryUserId" label="受益人"/><el-table-column label="试算金额"><template slot-scope="s">¥{{money(s.row.cappedAmount)}}</template></el-table-column></el-table>
      <span slot="footer"><el-button @click="trialVisible=false">关闭</el-button><el-button type="primary" @click="runTrial">执行试算</el-button></span>
    </el-dialog>

    <el-dialog title="审核发布规则" :visible.sync="publishVisible" width="560px"><el-alert title="发布后规则不可直接编辑；后续修改必须新建版本。" type="warning" :closable="false"/><el-form label-width="110px" style="margin-top:16px"><el-form-item label="生效时间"><el-date-picker v-model="publishForm.effectiveStartTime" type="datetime" value-format="yyyy-MM-dd HH:mm:ss"/></el-form-item><el-form-item label="失效时间"><el-date-picker v-model="publishForm.effectiveEndTime" type="datetime" value-format="yyyy-MM-dd HH:mm:ss" placeholder="留空表示长期"/></el-form-item><el-form-item label="发布说明"><el-input v-model.trim="publishForm.remark" type="textarea" :rows="3"/></el-form-item></el-form><span slot="footer"><el-button @click="publishVisible=false">取消</el-button><el-button type="primary" @click="publish">确认发布</el-button></span></el-dialog>
  </div>
</template>
<script>
import { getJkBusinessRoleList, getJkCommissionRuleList, saveJkCommissionRule } from '@/api/jkBusiness'
import { trialJkCommissionRule, publishJkCommissionRule, disableJkCommissionRule } from '@/api/jkV31Business'
const empty=()=>({ruleName:'',ruleCode:'',versionNo:1,ruleVersion:1,sourceType:'RETAIL_ORDER',rewardType:'DIRECT_RETAIL',receiverRoleCode:'',beneficiaryType:'DIRECT_PARENT_SNAPSHOT',baseType:'ITEM_PAID_AMOUNT',calculationType:'PERCENT',rate:null,fixedAmount:null,unitAmount:null,settleDelayDays:0,stackGroup:'',stackPolicy:'MAX_ONE',priority:0,perOrderCap:null,requiresRegisteredCustomer:false,requiresVoucher:false,requiresAudit:false,remark:''})
export default {data(){return{query:{sourceType:'',receiverRoleCode:'',status:null},list:[],loading:false,roleOptions:[],formVisible:false,form:empty(),trialVisible:false,trialRule:null,trialForm:{},trialResult:[],publishVisible:false,publishForm:{},sourceTypes:[{label:'线上零售',value:'RETAIL_ORDER'},{label:'线下销售',value:'OFFLINE_SALE'},{label:'平台订货',value:'PLATFORM_ORDER'},{label:'库存调拨',value:'STOCK_TRANSFER'},{label:'周期业绩',value:'PERFORMANCE_PERIOD'}],rewardTypes:[{label:'直属推荐',value:'DIRECT_RETAIL'},{label:'本人销售',value:'SELF_RETAIL'},{label:'团队管理',value:'TEAM_MANAGEMENT'},{label:'区域管理',value:'REGION_MANAGEMENT'},{label:'平台订货补贴',value:'PLATFORM_ORDER_SUBSIDY'},{label:'调拨平台补贴',value:'TRANSFER_PLATFORM_SUBSIDY'},{label:'调拨接收激励',value:'TRANSFER_RECEIVER_INCENTIVE'},{label:'阶梯奖励',value:'TIER_REWARD'}],beneficiaryTypes:[{label:'直属上级快照',value:'DIRECT_PARENT_SNAPSHOT'},{label:'区县代理快照',value:'COUNTY_AGENT_SNAPSHOT'},{label:'销售人快照',value:'SELLER_SNAPSHOT'},{label:'购买人快照',value:'PURCHASER_SNAPSHOT'},{label:'调拨发货人',value:'TRANSFER_SENDER_SNAPSHOT'},{label:'调拨收货人',value:'TRANSFER_RECEIVER_SNAPSHOT'},{label:'业绩归属人',value:'PERFORMANCE_OWNER'}],baseTypes:[{label:'商品实付金额',value:'ITEM_PAID_AMOUNT'},{label:'线下销售实付',value:'OFFLINE_SALE_PAID_AMOUNT'},{label:'平台订货金额',value:'PLATFORM_ORDER_AMOUNT'},{label:'调拨金额',value:'TRANSFER_AMOUNT'},{label:'有效业绩金额',value:'VALID_PERFORMANCE_AMOUNT'},{label:'真实经营毛利',value:'REAL_GROSS_PROFIT'},{label:'有效数量',value:'VALID_QUANTITY'}]}},created(){this.loadRoles();this.load()},methods:{unwrap(r){return(r&&r.data)||r||[]},loadRoles(){getJkBusinessRoleList({page:1,limit:100,enabled:true}).then(r=>this.roleOptions=this.unwrap(r))},load(){this.loading=true;getJkCommissionRuleList(this.query).then(r=>this.list=this.unwrap(r)).finally(()=>this.loading=false)},openRule(row){this.form=row?Object.assign(empty(),row):empty();this.formVisible=true},save(){if(!this.form.ruleName||!this.form.ruleCode||!this.form.receiverRoleCode)return this.$message.warning('请补齐必填项');saveJkCommissionRule(this.form).then(()=>{this.$message.success('草稿已保存');this.formVisible=false;this.load()})},openTrial(row){this.trialRule=row;this.trialForm={ruleId:row.id,scenario:'ADMIN_TRIAL',sourceType:row.sourceType,baseAmount:1000,realGrossProfit:200,quantity:1,sellerUserId:null,directParentUserId:null,countyAgentUserId:null,registeredCustomer:true,voucherPresent:true,audited:true};this.trialResult=[];this.trialVisible=true},runTrial(){trialJkCommissionRule(this.trialForm).then(r=>{this.trialResult=this.unwrap(r);if(!this.trialResult.length)this.$message.warning('当前规则未命中')})},openPublish(row){this.publishForm={ruleId:row.id,effectiveStartTime:'',effectiveEndTime:'',remark:''};this.publishVisible=true},publish(){if(!this.publishForm.effectiveStartTime||!this.publishForm.remark)return this.$message.warning('请填写生效时间和发布说明');publishJkCommissionRule(this.publishForm).then(()=>{this.$message.success('规则已发布');this.publishVisible=false;this.load()})},disableRule(row){this.$prompt('请输入停用原因','停用规则',{inputPattern:/\S+/,inputErrorMessage:'原因不能为空'}).then(({value})=>disableJkCommissionRule(row.id,value).then(()=>{this.$message.success('规则已停用');this.load()}))},calcText(row){if(row.calculationType==='PERCENT')return (row.rate==null?'--':row.rate+'%');if(row.calculationType==='FIXED_PER_QUANTITY')return '¥'+this.money(row.unitAmount)+'/件';return '¥'+this.money(row.fixedAmount)},rewardLabel(v){const x=this.rewardTypes.find(i=>i.value===v);return x?x.label:(v||'--')},publishTag(v){return v==='PUBLISHED'?'success':v==='DISABLED'?'info':'warning'},money(v){const n=Number(v||0);return Number.isNaN(n)?v:n.toFixed(2)}}}
</script>
<style scoped>.header{display:flex;align-items:center;justify-content:space-between}.danger{color:#f56c6c}.el-input-number{width:150px}</style>
